% Question 5
close all;
clc;

% Load patient 20 data
ABP_timeseries = readmatrix('s00020/s00020-2567-03-30-17-47_ABP.txt');

TCO_data = readmatrix('s00020/s00020-2567-03-30-17-47n.txt');

Fs = 125;

% 1st 12 hours
t_start_ABP = ABP_timeseries(1, 1);
t_start_TCO = TCO_data(1, 1);

ABP_window = ABP_timeseries(:, 1) < t_start_ABP + 12*60*60;

TCO_window = TCO_data(:, 1) < t_start_TCO + 12*60*60;

ABP_12h = ABP_timeseries(ABP_window, :);
TCO_12h = TCO_data(TCO_window, :);

ABP = ABP_12h(:, 2);

% Extract ABP features
addpath('PhysioToolkitCardiacOutput_MatlabCode/2analyze');

onset = wabp(ABP);
feat = abpfeature(ABP, onset);
beatq = jSQI(feat, onset, ABP);

% Parlikar estimation
[X, t, tau] = parlikarCO(ABP, onset, feat, beatq, Fs, 9);

% Thermodilution measurements
TCO = TCO_12h(:, 16);
validTCO = TCO > 0;

TCO_valid = TCO(validTCO);
time_TCO = TCO_12h(validTCO, 1)/60;

% Calibrate using 1st valid TCO measurement
firstIndex = find(validTCO, 1, 'first');

referenceCO = TCO(firstIndex);
referenceTime = TCO_12h(firstIndex, 1)/60;

calWindow = t > referenceTime - 1 & t <= referenceTime;
calValue = median(X(calWindow), 'omitnan');

if isempty(calValue) || ~isfinite(calValue) || calValue <= 0
    error('No valid estimate in calibration window!');
end

calibrationFactor = referenceCO/calValue;
CO_parlikar = calibrationFactor*X;

% Compare with thermodilution
% Match each TCO measurement to nearest Parlikar estimate
CO_matched = nan(size(TCO_valid));

for i = 1:length(TCO_valid)
    [~, idx] = min(abs(t - time_TCO(i)));

    if abs(t(idx) - time_TCO(i)) < 1
        CO_matched(i) = CO_parlikar(idx);
    end
end

% Excluded calibration measurement from performance evaluation
evaluation = isfinite(CO_matched);
evalaution(1) = false;

reference = TCO_valid(evaluation);
estimate = CO_matched(evaluation);

errorValues = estimate - reference;
bias = mean(errorValues);
RMSE = sqrt(mean(errorValues.^2));
percentageError = 100*std(errorValues)/mean(reference);

fprintf('\nParlikar performance - Patient 20\n'); %[output:7fc517c6]
fprintf('Bias: %.3f\n', bias); %[output:90175852]
fprintf('RMSE: %.3f\n', RMSE); %[output:8615a9f2]
fprintf('Percentage error: %2f%%\n', percentageError) %[output:14dcbd1e]

% Plot Parlikar and thermodilution CO
figure; %[output:05862461]

plot(t, CO_parlikar, 'LineWidth', 1.2); %[output:05862461]
hold on; %[output:05862461]

plot(time_TCO, TCO_valid, ':', 'LineWidth', 1.2) %[output:05862461]
xlabel('Time (minutes)'); %[output:05862461]
ylabel('Cardiac Output (l/min)'); %[output:05862461]
title('Parlikar CO Estimate - Patient 20'); %[output:05862461]
legend('ECO', 'TCO'); %[output:05862461]
grid on; %[output:05862461]

saveas(gcf, 'Parlikar_CO_Estimate_patient_20.png'); %[output:05862461]

% Plot estimated tau
figure; %[output:567eb915]

plot(t, tau, 'LineWidth', 1.2); %[output:567eb915]
xlabel('Time (minutes)'); %[output:567eb915]
ylabel('Tau (seconds)'); %[output:567eb915]
title('Parlikar Time Costant (Tau) Estimate'); %[output:567eb915]
grid on; %[output:567eb915]

saveas(gcf, 'Parlikar_Tau_Estimate_patient_20.png'); %[output:567eb915]

% Plot a comparison between true and estimated values
%figure;
%plot(time_TCO, reference, 'LineWidth', 1.2);
%hold on;
%
%plot(time_TCO, estimate, ':', 'LineWidth', 1.2);
%xlabel('Time (secs)');
%ylabel('Cardiac Output (l/min)');
%title('Parlikar vs Thermodilution CO - Patient 20');
%legend('TCO', 'ECO', 'Location', 'best');
%grid on;
%
%saveas(gcf, 'Parlikar_vs_Thermodilution_patient_20.png');


